using System.Globalization;
using System.Reflection;
using System.Text.Json;
using InstrumentComponents.Drivers.Catalog;
using OpenTap;
namespace InstrumentComponents.OpenTap.Tests;

// Fixed data originates in the preserved pre-cutover invoke spec and an
// independently selected set of nondefault values; never generated by the step emitter.
public sealed class OperationOracleTests
{
 [Theory][InlineData(false)][InlineData(true)]
 public void All74StepsForwardExactArgumentsAndPublishExactValuesBeforeAndAfterRoundTrip(bool roundTrip)
 {
  using var document=JsonDocument.Parse(File.ReadAllText(Path.Combine(RepoPaths.Root(),"validation/neutral/opentap-oracle.json")));
  var cases=document.RootElement.GetProperty("cases").EnumerateArray().ToArray();Assert.Equal(74,cases.Length);
  Assert.Equal(OpenTapCatalog.StepTypes().Select(t=>t.Name).Order(),cases.Select(c=>c.GetProperty("stepTypeName").GetString()!).Order());
  foreach(var row in cases)InstrumentSettingsScope.Run(()=>Execute(row,roundTrip));
 }
 private static void Execute(JsonElement row,bool roundTrip)
 {
  var type=typeof(DeviceInstrument).Assembly.GetType("InstrumentComponents.OpenTap."+row.GetProperty("stepTypeName").GetString())!;
  var step=(TestStep)Activator.CreateInstance(type)!;var instrumentProperty=type.GetProperty("Instrument")!;
  var resource=(DeviceInstrument)Activator.CreateInstance(instrumentProperty.PropertyType==typeof(DeviceInstrument)?typeof(DmmInstrument):instrumentProperty.PropertyType)!;
  resource.Name=type.Name+"-oracle";resource.VisaAddress="opaque://oracle";resource.DriverId="synthetic.opaque";
  InstrumentSettings.Current.Add(resource);instrumentProperty.SetValue(step,resource);
  foreach(var property in row.GetProperty("properties").EnumerateObject()){
   var info=type.GetProperty(property.Name)!;Assert.NotNull(info);info.SetValue(step,Value(property.Value,info.PropertyType));
  }
  var plan=new TestPlan();plan.ChildTestSteps.Add(step);var directory=Path.Combine(Path.GetTempPath(),"ic-oracle-"+Guid.NewGuid().ToString("N"));
  try{
   if(roundTrip){
    Directory.CreateDirectory(directory);var path=Path.Combine(directory,"Case.TapPlan");plan.Save(path);
    var settings=new TapSerializer().SerializeToString(InstrumentSettings.Current);InstrumentSettings.Current.Clear();
    using(var stream=new MemoryStream(System.Text.Encoding.UTF8.GetBytes(settings)))ComponentSettings.SetCurrent(stream);
    plan=TestPlan.Load(path);step=Assert.Single(plan.ChildTestSteps) as TestStep??throw new InvalidOperationException("Missing loaded step");
    var loaded=Assert.IsAssignableFrom<DeviceInstrument>(instrumentProperty.GetValue(step));Assert.NotSame(resource,loaded);resource=loaded;
   }
   foreach(var property in row.GetProperty("properties").EnumerateObject()){
    var info=type.GetProperty(property.Name)!;Assert.Equal(Value(property.Value,info.PropertyType),info.GetValue(step));
   }
   var backend=new OpaqueDevice();resource.AttachDevice(backend.OpenHandle(),true);var listener=new Values();
   var result=plan.Execute([listener]);Assert.True(result.Verdict==Verdict.Pass,type.Name+" "+result.Verdict+": "+step.Error);
   var calls=row.GetProperty("calls").EnumerateArray().ToArray();Assert.Equal(calls.Length,backend.Calls.Count);
   for(var i=0;i<calls.Length;i++){
    Assert.Equal(calls[i].GetProperty("operation").GetString(),backend.Calls[i].Operation.ToString());
    var expected=calls[i].GetProperty("arguments").EnumerateObject().ToDictionary(p=>p.Name,p=>p.Value);
    var actual=backend.Calls[i].Arguments;Assert.Equal(expected.Keys.Order(),actual.Keys.Order());
    foreach(var pair in expected){var argument=actual[pair.Key];var value=pair.Value;
     switch(value.ValueKind){
      case JsonValueKind.Null:Assert.Equal(ArgumentKind.OptionalNumber,argument.Kind);Assert.Null(argument.Number);break;
      case JsonValueKind.True:case JsonValueKind.False:Assert.Equal(ArgumentKind.Boolean,argument.Kind);Assert.Equal(value.GetBoolean(),argument.Bool);break;
      case JsonValueKind.String:Assert.Equal(ArgumentKind.Symbol,argument.Kind);Assert.Equal(value.GetString(),argument.Token);break;
      case JsonValueKind.Number:
       if(argument.Kind==ArgumentKind.Channel)Assert.Equal(value.GetUInt32(),argument.ChannelValue);
       else if(argument.Kind==ArgumentKind.Count)Assert.Equal(value.GetUInt32(),argument.CountValue);
       else{Assert.True(argument.Kind is ArgumentKind.Number or ArgumentKind.OptionalNumber);Assert.Equal(value.GetDouble(),argument.Number);}
       break;
      default:throw new InvalidOperationException("Unsupported oracle argument");
     }
    }
   }
   Assert.Equal(row.GetProperty("scalars").EnumerateArray().Select(v=>(v[0].GetDouble(),v[1].GetString()!)),listener.Scalars);
   Assert.Equal(row.GetProperty("samples").EnumerateArray().Select(v=>v.GetDouble()),listener.Samples);
   Assert.Equal(row.GetProperty("sampleUnits").EnumerateArray().Select(v=>v.GetString()!),listener.SampleUnits);
   Assert.Equal(row.GetProperty("identities").EnumerateArray().Select(v=>v.GetString()!),listener.Identities);
   Assert.Equal(1,backend.Opens);Assert.Equal(1,backend.Closes);Assert.False(resource.IsConnected);
  }finally{if(Directory.Exists(directory))Directory.Delete(directory,true);}
 }
 private static object? Value(JsonElement value,Type type){
  if(value.ValueKind==JsonValueKind.Null)return null;type=Nullable.GetUnderlyingType(type)??type;
  if(type.IsEnum)return Enum.Parse(type,value.GetString()!);
  if(type==typeof(string))return value.GetString();if(type==typeof(bool))return value.GetBoolean();
  return Convert.ChangeType(value.GetDouble(),type,CultureInfo.InvariantCulture);
 }
 private sealed class Values:ResultListener{
  public List<(double,string)> Scalars=[];public List<double> Samples=[];public List<string> SampleUnits=[];public List<string> Identities=[];
  public override void OnResultPublished(Guid stepRunId,ResultTable result){var columns=result.Columns.ToDictionary(c=>c.Name);
   if(result.Name==PhaseIResults.ScalarTable)Scalars.Add((Convert.ToDouble(columns["Value"].Data.GetValue(0)),(string)columns["Unit"].Data.GetValue(0)!));
   if(result.Name==PhaseIResults.SampleTable){Samples.Add(Convert.ToDouble(columns["Value"].Data.GetValue(0)));SampleUnits.Add((string)columns["Unit"].Data.GetValue(0)!);}
   if(result.Name==PhaseIResults.IdentityTable)Identities.Add((string)columns["Idn"].Data.GetValue(0)!);
  }
 }
}
